import{_ as c,r as e,o as l,c as i,e as t,a as n,d as a,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Behaviors - October CMS - 4.x","titleTemplate":false,"description":"Remix classes together with common functionality.","frontmatter":{"subtitle":"Remix classes together with common functionality."},"headers":[{"level":2,"title":"Comparison to Traits","slug":"comparison-to-traits","link":"#comparison-to-traits","children":[]},{"level":2,"title":"Extending Constructors","slug":"extending-constructors","link":"#extending-constructors","children":[{"level":3,"title":"Soft Definition","slug":"soft-definition","link":"#soft-definition","children":[]}]},{"level":2,"title":"Dynamically Implementing a Behavior","slug":"dynamically-implementing-a-behavior","link":"#dynamically-implementing-a-behavior","children":[]},{"level":2,"title":"Dynamically Creating Methods","slug":"dynamically-creating-methods","link":"#dynamically-creating-methods","children":[{"level":3,"title":"Checking the Existence of a Method","slug":"checking-the-existence-of-a-method","link":"#checking-the-existence-of-a-method","children":[]},{"level":3,"title":"List All Available Methods","slug":"list-all-available-methods","link":"#list-all-available-methods","children":[]}]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[{"level":3,"title":"Behavior / Extension class","slug":"behavior-extension-class","link":"#behavior-extension-class","children":[]},{"level":3,"title":"Extending a Class","slug":"extending-a-class","link":"#extending-a-class","children":[]},{"level":3,"title":"Using the Extension","slug":"using-the-extension","link":"#using-the-extension","children":[]}]}],"relativePath":"4.x/extend/system/behaviors.md","filePath":"4.x/extend/system/behaviors.md"}'),u={name:"4.x/extend/system/behaviors.md"};function k(d,s,h,m,g,f){const o=e("pre-heading"),p=e("post-heading");return l(),i("div",null,[t(o),s[0]||(s[0]=n("h1",null,"Behaviors",-1)),t(p),s[1]||(s[1]=n("p",null,[a("Behaviors add the ability for classes to have private traits that are similar to "),n("a",{href:"http://php.net/manual/en/language.oop5.traits.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("native PHP Traits"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(", except they have some distinct benefits.")],-1)),s[2]||(s[2]=r(`<ol><li>Behaviors use their own constructor.</li><li>Behaviors can have private or protected methods.</li><li>Methods and property names can conflict safely.</li><li>Classes can be extended with behaviors dynamically.</li></ol><h2 id="comparison-to-traits"><a href="#comparison-to-traits" class="header-anchor">#</a> Comparison to Traits</h2><p>Where you might use a PHP trait like this.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A behavior is used in a similar fashion.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyClass</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>UtilityFunctions</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>DeferredBinding</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Where you might define a trait like this.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">trait</span> <span class="token class-name-definition class-name">UtilityFunctions</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A behavior is defined like this.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UtilityFunctions</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$parent</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span> <span class="token operator">=</span> <span class="token variable">$parent</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string double-quoted-string">&quot;Hello from &quot;</span> <span class="token operator">.</span> <span class="token function">get_class</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">parent</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The extended object is always passed as the first argument to the constructor. In summary, when using behaviors extend the following classes.</p><ul><li>Extend <code>October\\Rain\\Extension\\ExtensionBase</code> to declare a class as a behavior.</li><li>Extend <code>October\\Rain\\Extension\\Extendable</code> as the class implementing the behavior.</li></ul><h2 id="extending-constructors"><a href="#extending-constructors" class="header-anchor">#</a> Extending Constructors</h2><p>Any class that extends the <code>Extendable</code> class can have its constructor extended with the static <code>extend</code> method. The argument should pass a closure that will be called as part of the class constructor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">MyClass</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="soft-definition"><a href="#soft-definition" class="header-anchor">#</a> Soft Definition</h3><p>If a behavior class does not exist, like a trait, a <strong>class not found</strong> error will be thrown. In some cases you may wish to suppress this error, for conditional implementation if a behavior is present in the system. You can do this by placing an <code>@</code> symbol at the beginning of the class name. In the following example, if the class name <code>RainLab\\Translate\\Behaviors\\TranslatableModel</code> does not exist, no error will be thrown.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;@&#39;</span><span class="token operator">.</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>Translate<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>TranslatableModel</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="dynamically-implementing-a-behavior"><a href="#dynamically-implementing-a-behavior" class="header-anchor">#</a> Dynamically Implementing a Behavior</h2><p>This unique ability to extend constructors allows behaviors to be implemented dynamically, for example, use the <code>implementClassWith</code> method to implement the <code>RelationController</code> class in the <code>UsersController</code> class.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">UsersController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">implementClassWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>The <code>implementClassWith</code> method can be called multiple times safely, it will check if the class is already implementing the behavior and implement it.</p></div><p>Use the <code>extendClassWith</code> method to extend an object after it has been constructed. The following example would dynamically extend a Model class using a class name stored in the database.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterFetch</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">extendClassWith</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">class_type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To check if an object has been extended with a behavior, you may use the <code>isClassExtendedWith</code> method on the object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">isClassExtendedWith</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To specifically call a method from a behavior, use the <code>asExtension</code> method which takes the class base name or the fully qualified class as its argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;RelationController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="dynamically-creating-methods"><a href="#dynamically-creating-methods" class="header-anchor">#</a> Dynamically Creating Methods</h2><p>Methods can be created to an extendable object by calling <code>addDynamicMethod</code> and passing a method name and callable object, like a <code>Closure</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">MyModel</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDynamicMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;...&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="checking-the-existence-of-a-method"><a href="#checking-the-existence-of-a-method" class="header-anchor">#</a> Checking the Existence of a Method</h3><p>To check for the existence of a method in an <code>Extendable</code> class call the <code>methodExists</code> method - similar to the PHP <code>method_exists()</code> function. This will detect both standard methods, methods in behaviors and dynamic methods that have been added through a <code>addDynamicMethod</code> call.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;getTagsAttribute&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">methodExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;missingMethod&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span>
</code></pre></div><h3 id="list-all-available-methods"><a href="#list-all-available-methods" class="header-anchor">#</a> List All Available Methods</h3><p>To retrieve a list of all available methods in an <code>Extendable</code> class, you can use the <code>getClassMethods</code> method. This method operates similar to the PHP <code>get_class_methods()</code> function in that it returns an array of available methods in a class, but in addition to defined methods in the class, it will also list any methods provided by an extension or through an <code>addDynamicMethod</code> call.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$methods</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">getClassMethods</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">/**
 * $methods = [
 *   0 =&gt; &#39;__construct&#39;,
 *   1 =&gt; &#39;extend&#39;,
 *   2 =&gt; &#39;getTagsAttribute&#39;,
 *   ...
 * ];
 */</span>
</code></pre></div><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><h3 id="behavior-extension-class"><a href="#behavior-extension-class" class="header-anchor">#</a> Behavior / Extension class</h3><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">MyNamespace<span class="token punctuation">\\</span>Behaviors</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FormController</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>ExtensionBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var Controller controller is a reference to the extended object.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * __construct
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the FormController Behavior!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;You might not see me...&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-a-class"><a href="#extending-a-class" class="header-anchor">#</a> Extending a Class</h3><p>This <code>Controller</code> class will implement the <code>FormController</code> behavior and then the methods will become available (mixed in) to the class. We will override the <code>otherMethod</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">MyNamespace</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Controller</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Extension<span class="token punctuation">\\</span>Extendable</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * implement the FormController behavior
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>MyNamespace<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I come from the main Controller!&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><h3 id="using-the-extension"><a href="#using-the-extension" class="header-anchor">#</a> Using the Extension</h3><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$controller</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">MyNamespace<span class="token punctuation">\\</span>Controller</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the FormController Behavior!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">someMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: I come from the main Controller!</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Prints: You might not see me...</span>
<span class="token keyword">echo</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">otherMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,45))])}const b=c(u,[["render",k]]);export{v as __pageData,b as default};
